#[test]
fn configured_acp_route_can_start_before_runtime_discovery() {
    let mut router = AiExecutionRouter::default();
    router
        .set_acp_route("model:managed_local", "goose.managed-local")
        .expect("route");
    let resolution = router
        .resolve_for_startup("model:managed_local:model-a", "model:managed_local")
        .expect("configured route");
    assert_eq!(
        resolution.driver,
        AiExecutionDriver::Acp {
            agent_id: "goose.managed-local".to_owned(),
        }
    );
    assert!(matches!(
        router.resolve("model:managed_local:model-a", "model:managed_local"),
        Err(AiExecutionRoutingError::AcpAgentUnavailable { .. })
    ));
}

